import React, { useEffect, useState } from "react";
import io from "socket.io-client";
import { AuthProvider } from "./Context/AuthContext";
import CanvasBoard from "./components/CanvasBoard";
import ToolBar from "./components/ToolBar";
import UserList from "./components/UserList";
import LoginForm from "./components/LoginForm";

const socket = io("http://localhost:5000");

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);

  useEffect(() => {
    // Listen for user list updates
    socket.on("userList", (userList) => {
      setUsers(userList);
    });

    // Listen for clear board events
    socket.on("clearBoard", () => {
      const canvas = document.querySelector("canvas");
      if (canvas) {
        const ctx = canvas.getContext("2d");
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        // Reset to white background
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
    });

    return () => {
      socket.off("userList");
      socket.off("clearBoard");
    };
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    setIsLoggedIn(true);
    // Notify server about user joining
    socket.emit("userJoined", userData);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUser(null);
    socket.disconnect();
    // Reconnect socket for new session
    socket.connect();
  };

  if (!isLoggedIn) {
    return (
      <AuthProvider>
        <LoginForm onLogin={handleLogin} />
      </AuthProvider>
    );
  }

  return (
    <AuthProvider>
      <div className="h-screen flex flex-col bg-gradient-to-br from-gray-50 to-blue-50">
        {/* Enhanced Header */}
        <div className="relative overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-blue-600 via-purple-600 to-indigo-600"></div>
          <div className="absolute inset-0 opacity-30" style={{
            backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.1'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`
          }}></div>
          
          <div className="relative flex items-center justify-between p-6">
            <div className="flex items-center space-x-4">
              <div className="w-12 h-12 bg-white/20 backdrop-blur-sm rounded-xl flex items-center justify-center shadow-lg">
                <svg className="w-7 h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                </svg>
              </div>
              <div>
                <h1 className="text-3xl font-bold text-white drop-shadow-lg">
                  Collaborative Whiteboard
                </h1>
                <p className="text-blue-100 text-sm">
                  Real-time drawing collaboration
                </p>
              </div>
            </div>
            
            <div className="flex items-center space-x-4">
              <div className="bg-white/20 backdrop-blur-sm rounded-xl px-4 py-2 text-white">
                <span className="font-medium">Welcome, {user?.username}</span>
                <span className="ml-2 px-2 py-1 bg-white/20 rounded-lg text-xs">
                  {user?.role === 'admin' && '👑'}
                  {user?.role === 'editor' && '✏️'}
                  {user?.role === 'viewer' && '👁️'}
                  {user?.role}
                </span>
              </div>
              <button
                onClick={handleLogout}
                className="px-6 py-2 bg-red-500/80 hover:bg-red-600/80 text-white rounded-xl hover:shadow-lg transition-all duration-200 backdrop-blur-sm border border-white/20"
              >
                <div className="flex items-center space-x-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                  </svg>
                  <span>Logout</span>
                </div>
              </button>
            </div>
          </div>
        </div>
        
        <ToolBar socket={socket} />
        
        <div className="flex-1 flex">
          <div className="flex-1">
            <CanvasBoard socket={socket} />
          </div>
          <UserList users={users} />
        </div>
      </div>
    </AuthProvider>
  );
}

export default App;
